#[allow(dead_code)]
#[derive(Debug, Clone, Copy)]
enum BridgeError {
    NullPtr,
    Utf8,
    ChainId,
    Authority,
    AssetDefinition,
    Destination,
    Quantity,
    InvalidTtl,
    InvalidNonce,
    PrivateKey,
    Alloc,
    HashOutBuffer,
    InvalidNoteCommitment,
    ConfidentialPayload,
    ProofAttachment,
    InvalidNullifiers,
    InvalidRootHint,
    AssetId,
    JsonSerialize,
    KagemushaProve,
    KagemushaRecursiveSpendV4Unavailable,
    KagemushaRecursiveSpendV4Artifact,
    KagemushaBusy,
    UnsupportedAlgorithm,
    MetadataTarget,
    MetadataKey,
    MetadataValue,
    Governance,
    Hex,
    AccountList,
    MultisigSpec,
    IdentifierReceipt,
    VerifyingKeyId,
    ZkAssetMode,
    SecpParse,
    SecpSign,
    SecpVerify,
    TransactionSign,
    FeePayment,
    ConnectKeypair,
    AccountOnboardingBody,
    AliasInstruction,
    DetachedTransactionScaffold,
    DetachedTransactionSignature,
    CanonicalJson,
    ValidationFeePolicyProof,
}

impl BridgeError {
    const fn code(self) -> c_int {
        match self {
            BridgeError::NullPtr => ERR_NULL_PTR,
            BridgeError::Utf8 => ERR_UTF8,
            BridgeError::ChainId => ERR_CHAIN_ID_PARSE,
            BridgeError::Authority => ERR_AUTHORITY_PARSE,
            BridgeError::AssetDefinition => ERR_ASSET_DEFINITION_PARSE,
            BridgeError::Destination => ERR_DESTINATION_PARSE,
            BridgeError::Quantity => ERR_QUANTITY_PARSE,
            BridgeError::InvalidTtl => ERR_INVALID_TTL,
            BridgeError::InvalidNonce => ERR_INVALID_NONCE,
            BridgeError::PrivateKey => ERR_PRIVATE_KEY_PARSE,
            BridgeError::Alloc => ERR_ALLOC,
            BridgeError::HashOutBuffer => ERR_HASH_OUT_LEN,
            BridgeError::InvalidNoteCommitment => ERR_INVALID_NOTE_COMMITMENT,
            BridgeError::ConfidentialPayload => ERR_CONFIDENTIAL_PAYLOAD,
            BridgeError::ProofAttachment => ERR_PROOF_ATTACHMENT,
            BridgeError::InvalidNullifiers => ERR_INVALID_NULLIFIERS,
            BridgeError::InvalidRootHint => ERR_INVALID_ROOT_HINT,
            BridgeError::AssetId => ERR_ASSET_ID_PARSE,
            BridgeError::JsonSerialize => ERR_JSON_SERIALIZE,
            BridgeError::KagemushaProve => ERR_KAGEMUSHA_PROVE,
            BridgeError::KagemushaRecursiveSpendV4Unavailable => {
                ERR_KAGEMUSHA_RECURSIVE_SPEND_V4_UNAVAILABLE
            }
            BridgeError::KagemushaRecursiveSpendV4Artifact => {
                ERR_KAGEMUSHA_RECURSIVE_SPEND_V4_ARTIFACT
            }
            BridgeError::KagemushaBusy => ERR_KAGEMUSHA_BUSY,
            BridgeError::UnsupportedAlgorithm => ERR_UNSUPPORTED_ALGORITHM,
            BridgeError::MetadataTarget => ERR_METADATA_TARGET,
            BridgeError::MetadataKey => ERR_METADATA_KEY,
            BridgeError::MetadataValue => ERR_METADATA_VALUE,
            BridgeError::Governance => ERR_GOVERNANCE,
            BridgeError::Hex => ERR_HEX,
            BridgeError::AccountList => ERR_ACCOUNT_LIST,
            BridgeError::MultisigSpec => ERR_MULTISIG_SPEC,
            BridgeError::IdentifierReceipt => ERR_IDENTIFIER_RECEIPT,
            BridgeError::VerifyingKeyId => ERR_VERIFYING_KEY_ID,
            BridgeError::ZkAssetMode => ERR_ZK_ASSET_MODE,
            BridgeError::SecpParse => ERR_SECP_PARSE,
            BridgeError::SecpSign => ERR_SECP_SIGN,
            BridgeError::SecpVerify => ERR_SECP_VERIFY,
            BridgeError::TransactionSign => ERR_TRANSACTION_SIGN,
            BridgeError::FeePayment => ERR_FEE_PAYMENT,
            BridgeError::ConnectKeypair => ERR_CONNECT_KEYPAIR,
            BridgeError::AccountOnboardingBody => ERR_ACCOUNT_ONBOARDING_BODY,
            BridgeError::AliasInstruction => ERR_ALIAS_INSTRUCTION,
            BridgeError::DetachedTransactionScaffold => ERR_DETACHED_TRANSACTION_SCAFFOLD,
            BridgeError::DetachedTransactionSignature => ERR_DETACHED_TRANSACTION_SIGNATURE,
            BridgeError::CanonicalJson => ERR_CANONICAL_JSON,
            BridgeError::ValidationFeePolicyProof => ERR_VALIDATION_FEE_POLICY_PROOF,
        }
    }
}

type BridgeResult<T> = Result<T, BridgeError>;

/// Stack reserved for one ABI-21 Kagemusha artifact/proof execution boundary.
///
/// Mobile callers enter the bridge on Swift- and ART-owned threads whose stack
/// size is outside Rust's control. Keep the resource-heavy authenticated
/// artifact parsing and Halo2 lifecycle execution on a Rust-owned stack so a
/// caller's executor stack cannot determine whether offline cash succeeds.
const KAGEMUSHA_RECURSIVE_SPEND_WORKER_STACK_BYTES_V4: usize = 64 * 1024 * 1024;

/// Process-wide permit for the parsed-artifact and Halo2 lifecycle boundary.
///
/// A single authenticated prover already owns both Pasta parameter sets and
/// proving keys. Allowing two mobile callers to parse and prove concurrently
/// would multiply that release-sized heap even when each individual operation
/// stays within its budget. The permit carries no mutable protocol state, so a
/// worker panic must not poison future offline-cash operations.
static KAGEMUSHA_RECURSIVE_SPEND_LIFECYCLE_PERMIT_V4: OnceLock<Mutex<()>> = OnceLock::new();

fn kagemusha_recursive_spend_lifecycle_permit_v4() -> &'static Mutex<()> {
    KAGEMUSHA_RECURSIVE_SPEND_LIFECYCLE_PERMIT_V4.get_or_init(|| Mutex::new(()))
}

fn run_kagemusha_recursive_spend_worker_v4<T, F>(
    thread_name: &'static str,
    boundary_error: BridgeError,
    work: F,
) -> BridgeResult<T>
where
    T: Send,
    F: FnOnce() -> BridgeResult<T> + Send,
{
    std::thread::scope(|scope| {
        let worker = std::thread::Builder::new()
            .name(thread_name.to_owned())
            .stack_size(KAGEMUSHA_RECURSIVE_SPEND_WORKER_STACK_BYTES_V4)
            .spawn_scoped(scope, move || {
                let _permit = kagemusha_recursive_spend_lifecycle_permit_v4()
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                work()
            })
            .map_err(|_| boundary_error)?;
        worker.join().map_err(|_| boundary_error)?
    })
}

/// Return the current native bridge C ABI version.
///
/// Clients that resolve symbols dynamically must check this before calling other
/// entrypoints; stale bridge artifacts can otherwise crash before Rust receives
/// enough arguments to validate the call.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn connect_norito_bridge_abi_version() -> u32 {
    CONNECT_NORITO_BRIDGE_ABI_VERSION
}

fn native_signer_jni_contract_revision() -> u32 {
    NATIVE_SIGNER_JNI_CONTRACT_REVISION
}

fn account_address_error_fields(err: &AccountAddressError) -> Option<JsonMap> {
    use AccountAddressError::*;

    let mut fields = JsonMap::new();
    match err {
        UnsupportedAlgorithm(algorithm) => {
            fields.insert("algorithm".into(), JsonValue::from(algorithm.to_string()));
        }
        KeyPayloadTooLong(len) => {
            fields.insert("length".into(), JsonValue::from(u64::from(*len)));
        }
        InvalidHeaderVersion(value) => {
            fields.insert("value".into(), JsonValue::from(u64::from(*value)));
        }
        InvalidNormVersion(value) => {
            fields.insert("value".into(), JsonValue::from(u64::from(*value)));
        }
        InvalidDomainLabel(label) => {
            fields.insert("label".into(), JsonValue::from(label.to_string()));
        }
        UnexpectedNetworkPrefix { expected, found } => {
            fields.insert("expected".into(), JsonValue::from(u64::from(*expected)));
            fields.insert("found".into(), JsonValue::from(u64::from(*found)));
        }
        UnknownAddressClass(value) | UnknownControllerTag(value) => {
            fields.insert("value".into(), JsonValue::from(u64::from(*value)));
        }
        UnknownCurve(value) => {
            fields.insert("value".into(), JsonValue::from(u64::from(*value)));
        }
        InvalidI105Char(ch) => {
            fields.insert("char".into(), JsonValue::from(ch.to_string()));
        }
        MultisigMemberOverflow(count) => {
            fields.insert("count".into(), JsonValue::from(*count as u64));
        }
        InvalidMultisigPolicy(policy) => {
            fields.insert("policy_error".into(), JsonValue::from(policy.to_string()));
        }
        _ => {}
    }

    if fields.is_empty() {
        None
    } else {
        Some(fields)
    }
}

fn encode_account_address_error(err: AccountAddressError) -> Vec<u8> {
    let mut map = JsonMap::new();
    map.insert("code".into(), JsonValue::from(err.code_str()));
    map.insert("message".into(), JsonValue::from(err.to_string()));
    if let Some(fields) = account_address_error_fields(&err) {
        map.insert("fields".into(), JsonValue::Object(fields));
    }
    norito::json::to_vec(&JsonValue::Object(map))
        .unwrap_or_else(|_| b"{\"code\":\"ERR_ADDRESS_PARSE\"}".to_vec())
}

fn write_account_address_error(
    err: AccountAddressError,
    out_ptr: *mut *mut c_uchar,
    out_len: *mut c_ulong,
) -> c_int {
    if !out_ptr.is_null() {
        unsafe { *out_ptr = ptr::null_mut() };
    }
    if !out_len.is_null() {
        unsafe { *out_len = 0 };
    }
    if out_ptr.is_null() || out_len.is_null() {
        return ERR_ACCOUNT_ADDRESS;
    }
    let payload = encode_account_address_error(err);
    match unsafe { write_bytes(out_ptr, out_len, &payload) } {
        Ok(()) => ERR_ACCOUNT_ADDRESS,
        Err(code) => code,
    }
}

unsafe fn read_string_bridge(ptr: *const c_char, len: c_ulong) -> BridgeResult<String> {
    if ptr.is_null() {
        return Err(BridgeError::NullPtr);
    }
    let slice = unsafe { slice::from_raw_parts(ptr as *const u8, len as usize) };
    let s = std::str::from_utf8(slice).map_err(|_| BridgeError::Utf8)?;
    Ok(s.to_owned())
}

unsafe fn write_bytes(
    out_ptr: *mut *mut c_uchar,
    out_len: *mut c_ulong,
    bytes: &[u8],
) -> Result<(), c_int> {
    if out_ptr.is_null() || out_len.is_null() {
        return Err(ERR_NULL_PTR);
    }
    let len = bytes.len();
    if len == 0 {
        unsafe {
            *out_ptr = ptr::null_mut();
            *out_len = 0;
        }
        return Ok(());
    }
    let mem = unsafe { malloc(len) };
    if mem.is_null() {
        return Err(ERR_ALLOC);
    }
    unsafe {
        ptr::copy_nonoverlapping(bytes.as_ptr(), mem as *mut u8, len);
        *out_ptr = mem as *mut u8;
        *out_len = len as c_ulong;
    }
    Ok(())
}

unsafe fn write_bytes_usize(
    out_ptr: *mut *mut c_uchar,
    out_len: *mut usize,
    bytes: &[u8],
) -> Result<(), c_int> {
    if out_ptr.is_null() || out_len.is_null() {
        return Err(ERR_NULL_PTR);
    }
    let len = bytes.len();
    if len == 0 {
        unsafe {
            *out_ptr = ptr::null_mut();
            *out_len = 0;
        }
        return Ok(());
    }
    let mem = unsafe { malloc(len) };
    if mem.is_null() {
        return Err(ERR_ALLOC);
    }
    unsafe {
        ptr::copy_nonoverlapping(bytes.as_ptr(), mem.cast::<u8>(), len);
        *out_ptr = mem.cast::<u8>();
        *out_len = len;
    }
    Ok(())
}

unsafe fn write_bytes_bridge(
    out_ptr: *mut *mut c_uchar,
    out_len: *mut c_ulong,
    bytes: &[u8],
) -> BridgeResult<()> {
    unsafe { write_bytes(out_ptr, out_len, bytes) }.map_err(|code| match code {
        ERR_NULL_PTR => BridgeError::NullPtr,
        ERR_ALLOC => BridgeError::Alloc,
        _ => BridgeError::Alloc,
    })
}

fn kagemusha_archive_out_of_bounds(len: usize) -> bool {
    len == 0 || len > KAGEMUSHA_NATIVE_ARCHIVE_MAX_BYTES
}

fn kagemusha_archive_out_of_bounds_for(len: usize, maximum: usize) -> bool {
    len == 0 || len > maximum
}

unsafe fn read_kagemusha_archive_bytes_bounded(
    ptr: *const c_uchar,
    len: c_ulong,
    maximum: usize,
) -> BridgeResult<Vec<u8>> {
    if ptr.is_null() {
        return Err(BridgeError::NullPtr);
    }
    let len: usize = len.try_into().map_err(|_| BridgeError::KagemushaProve)?;
    if kagemusha_archive_out_of_bounds_for(len, maximum) {
        return Err(BridgeError::KagemushaProve);
    }
    unsafe { read_vec_bytes(ptr, len as c_ulong) }
}

trait KagemushaSensitiveArchive {
    fn zeroize_sensitive(&mut self);
}

fn kagemusha_canonical_decode_limits_with_profile(
    encoded_len: usize,
    extra_encoded_allocation_multiplier: usize,
    fixed_allocation_allowance: usize,
) -> norito::DecodeLimits {
    // Every variable-length member must be represented in the exact
    // uncompressed canonical frame. These limits therefore scale from the
    // already capped archive. One fixed 64 KiB allowance covers decoded enum,
    // collection, and string bookkeeping whose size does not shrink in direct
    // proportion to a small payload. Fixed-depth proof schemas pass their
    // protocol-derived allowance. Schemas with nested collections whose
    // cardinality is validated after reconstruction restore Norito's generic
    // 32-fold frame-scaled ceiling through their explicit profile.
    norito::DecodeLimits::new(
        encoded_len,
        encoded_len,
        encoded_len.saturating_mul(2),
        encoded_len
            .saturating_mul(
                KAGEMUSHA_CANONICAL_TOTAL_ALLOCATION_MULTIPLIER
                    .saturating_add(extra_encoded_allocation_multiplier),
            )
            .saturating_add(fixed_allocation_allowance),
        KAGEMUSHA_CANONICAL_MAX_NESTING_DEPTH,
    )
}

fn kagemusha_canonical_decode_limits(encoded_len: usize) -> norito::DecodeLimits {
    kagemusha_canonical_decode_limits_with_profile(
        encoded_len,
        0,
        KAGEMUSHA_CANONICAL_FIXED_ALLOCATION_ALLOWANCE,
    )
}

/// Exact allocation profile for one canonical mobile/native archive schema.
/// There is intentionally no blanket implementation: adding a decoded schema
/// requires an explicit proof-depth or structural classification.
trait KagemushaCanonicalDecodeSchema {
    const EXTRA_ENCODED_ALLOCATION_MULTIPLIER: usize = 0;
    const FIXED_ALLOCATION_ALLOWANCE: usize;

    fn preflight_canonical_archive(_bytes: &[u8]) -> Result<(), norito::Error> {
        Ok(())
    }
}

macro_rules! impl_kagemusha_canonical_decode_schema {
    ($allowance:expr; $($ty:ty),+ $(,)?) => {
        $(
            impl KagemushaCanonicalDecodeSchema for $ty {
                const FIXED_ALLOCATION_ALLOWANCE: usize = $allowance;
            }
        )+
    };
}

macro_rules! impl_kagemusha_canonical_decode_profile {
    ($extra:expr, $allowance:expr; $($ty:ty),+ $(,)?) => {
        $(
            impl KagemushaCanonicalDecodeSchema for $ty {
                const EXTRA_ENCODED_ALLOCATION_MULTIPLIER: usize = $extra;
                const FIXED_ALLOCATION_ALLOWANCE: usize = $allowance;
            }
        )+
    };
}

