        assert!(header.contains("#define CONNECT_NORITO_ERR_KAGEMUSHA_BUSY -318"));

        let swift = include_str!("../../../IrohaSwift/Sources/IrohaSwift/NativeBridge.swift");
        assert!(swift.contains("case kagemushaBusy"));
