        let swift_lifecycle =
            include_str!("../../../IrohaSwift/Sources/IrohaSwift/KagemushaRecursiveSpendV4.swift");
        assert!(swift_lifecycle.contains("catch NativeBridgeError.kagemushaBusy"));
