fn java_sorafs_orderbook_provider_id(bytes: Vec<u8>) -> Result<Option<[u8; 32]>, String> {
    if bytes.is_empty() {
        return Ok(None);
    }
    let provider_id = java_sorafs_orderbook_fixed32(bytes, "providerId")?;
    if provider_id == [0; 32] {
        return Err("providerId must not be all zero".to_owned());
    }
    Ok(Some(provider_id))
}

