fn java_optional_text_array(
    env: &mut jni::JNIEnv<'_>,
    array: &jni::objects::JByteArray<'_>,
    present: jni::sys::jboolean,
    context: &str,
) -> Result<Option<String>, String> {
    if present == 0 {
        return Ok(None);
    }
    java_text_array(env, array, context).map(Some)
}

