fn java_optional_root_hint(bytes: &[u8]) -> Result<Option<[u8; 32]>, String> {
    if bytes.is_empty() {
        return Ok(None);
    }
    if bytes.len() != 32 {
        return Err("rootHint must be exactly 32 bytes when provided".to_owned());
    }
    let mut root = [0u8; 32];
    root.copy_from_slice(bytes);
    Ok(Some(root))
}

